        id, label,
        createWidget(host) {
          let active = true;
          const handle = mountEditor(host, draft => {
            if (active) editor.draft = draft;
          });
          return {
            destroy() {
              active = false;
              handle.destroy();
            }
          };
        }
      });
      view.showChildView('editor', editor);
      return editor;
    },
    closeEditor() { view.getRegion('editor').empty(); },
    destroy() { view.destroy(); }
  };
}
